from pathlib import Path
import json,shutil
ROOT=Path(__file__).resolve().parent.parent
APPS=[('places-in-the-quran','Quranic Places Atlas','Read the passages, explore the geography, and see what remains uncertain.','teal'),('word-groups','Islamic Concept Connections','Find four groups of related Islamic terms in a sixteen-tile puzzle.','blue'),('islamic-history-timeline-challenge','Islamic History Timeline Challenge','Arrange sourced events and explore the sequence behind them.','violet'),('understand-your-salah','Understand Salah Lab','Explore the words of prayer, one recitation at a time.','teal'),('parables-of-the-quran','Quranic Parables Studio','Explore Quranic comparisons through passages and interactive reading diagrams.','blue')]
seed=ROOT/'apps/quran-concept-atlas'
for i,(slug,name,description,accent) in enumerate(APPS):
 app=ROOT/'apps'/slug
 if (app/'package.json').exists():raise RuntimeError('Refusing to overwrite '+slug)
 for d in ['src/pages','src/layouts','src/lib','src/data','src/styles','tests','public/fonts']:(app/d).mkdir(parents=True,exist_ok=True)
 for f in ['astro.config.mjs','tsconfig.json','LICENSE','public/favicon.svg','public/_headers','public/robots.txt','src/pages/privacy.astro','src/pages/404.astro','src/layouts/Shell.astro','src/lib/utils.ts','src/lib/shell.ts','src/styles/global.css','tests/storage.test.ts']:
  shutil.copyfile(seed/f,app/f)
 for f in (seed/'public/fonts').iterdir():shutil.copyfile(f,app/'public/fonts'/f.name)
 package=json.loads((seed/'package.json').read_text(encoding='utf-8'));package['name']=slug
 for key in ['dev','preview']:package['scripts'][key]=package['scripts'][key].replace('4328',str(4331+i))
 (app/'package.json').write_text(json.dumps(package,indent=2)+'\n',encoding='utf-8')
 (app/'src/data/config.json').write_text(json.dumps(dict(slug=slug,name=name,description=description,accent=accent,port=4331+i),indent=2),encoding='utf-8')
 (app/'src/pages/sources.astro').write_text('''---
import Shell from '../layouts/Shell.astro';import sources from '../data/sources.json';import provenance from '../data/provenance.json';import content from '../data/content.json';
---
<Shell title="Sources & methodology" active="sources"><article class="prose"><span class="eyebrow">Read the source</span><h1>Sources & methodology</h1><p>{content.methodology}</p><h2>Canonical text</h2><p>Quran text comes from <a href="https://mcp.quran.ai">Quran Foundation's official Quran MCP</a>. Arabic is Uthmani Hafs, <code>ar-uthmani-hafs</code>. English is Marmaduke Pickthall, <code>en-pickthall</code>, whose historical public-domain wording is preserved. New commentary anchors were fetched using <code>fetch_tafsir</code>, edition <code>ar-muyassar</code>, the King Fahd Quran Printing Complex committee's concise Arabic commentary. Commentary summaries are original English paraphrases checked against that retrieved Arabic; full commentary is not republished.</p><p>Hadith references identify the named report on Sunnah.com. Ancient Arabic prayer excerpts are distinguished from Quran text. Their English meanings are our concise renderings from the Arabic, not quotations of modern English hadith translations. Valid narrated variants exist; this is a meaning study, not a complete prayer manual or a ruling on prayer validity.</p><h2>Provenance and reuse</h2><p>Canonical snapshot retrieved {provenance.retrievedAt.slice(0,10)}. Additional commentary and reference checks completed for this batch. Source records, checksums, and edition names ship with each project. Activity groupings and questions are editorial learning aids, not scholarly certification.</p><p class="micro">Snapshot SHA-256: <code style="overflow-wrap:anywhere">{provenance.snapshotSha256}</code></p><p>Original app code is MIT licensed. DM Sans, Newsreader and Amiri are local SIL Open Font License assets. Other media keep the terms listed below and in their bundled attribution files. No personal blogs are used.</p><h2>References and media</h2><ul class="source-list">{sources.map(s=><li><a href={s.url} target="_blank" rel="noopener noreferrer">{s.label} ↗</a><small>{s.kind} · {s.note}</small></li>)}</ul><button class="button secondary" data-print>Print sources</button></article></Shell>
''',encoding='utf-8')
 (app/'README.md').write_text(f'''# {name}\n\n{description}\n\nIndependent Astro 7.4.2 static app using Bun 1.4.4.\n\n```sh\nbun install --frozen-lockfile\nbun run dev\nbun run check\nbun test\nbun run build\n```\n\nPort {4331+i}. Cloudflare Pages project root `apps/{slug}`, build command `bun install --frozen-lockfile && bun run build`, output `dist`, environment `BUN_VERSION=1.4.4`. No adapter, server, secrets, account, or runtime external API. Host at the root of its own domain or Pages project.\n\nEach project bundles its fonts and content, light/dark themes, citations, privacy controls and 404 page. Optional localStorage expires on access after 30 days. Quran text and commentary were fetched through the official Quran MCP. See the Sources page and `src/data/provenance.json` for editions, editorial limits and media attribution. Build outputs are packaged in `release/{slug}-pages.zip` at repository level.\n''',encoding='utf-8')
 print(slug)
